#[cfg(test)]
static PROFILE: std::sync::Mutex<std::collections::BTreeMap<String, (u64, std::time::Duration)>> = std::sync::Mutex::new(std::collections::BTreeMap::new());
#[cfg(test)]
pub(crate) struct ProfileScope(String, std::time::Instant);
#[cfg(test)]
impl ProfileScope { pub(crate) fn new(name: impl Into<String>) -> Self { Self(name.into(), std::time::Instant::now()) } }
#[cfg(test)]
impl Drop for ProfileScope { fn drop(&mut self) { let elapsed = self.1.elapsed(); let mut profiles = PROFILE.lock().unwrap(); let entry = profiles.entry(self.0.clone()).or_default(); entry.0 += 1; entry.1 += elapsed; } }
#[cfg(test)]
pub(crate) fn profile_take() -> Vec<(String, u64, f64)> {
    std::mem::take(&mut *PROFILE.lock().unwrap()).into_iter().map(|(name,(count,elapsed))| (name,count,elapsed.as_secs_f64()*1000.0)).collect()
}
